// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/v1/events", wrapper.ListEvents)

	router.Post(options.BaseURL+"/v1/events", wrapper.CreateEvent)

	router.Get(options.BaseURL+"/v1/events/search", wrapper.SearchEvents)

	router.Delete(options.BaseURL+"/v1/events/:eventId", wrapper.DeleteEvent)

	router.Get(options.BaseURL+"/v1/events/:eventId", wrapper.GetEvent)

	router.Patch(options.BaseURL+"/v1/events/:eventId", wrapper.UpdateEvent)

	router.Get(options.BaseURL+"/v1/events/:eventId/occurrences/:recurrenceId", wrapper.GetEventOccurrence)

	router.Patch(options.BaseURL+"/v1/events/:eventId/occurrences/:recurrenceId", wrapper.UpdateEventOccurrence)

	router.Post(options.BaseURL+"/v1/events/:eventId/occurrences/:recurrenceId/split", wrapper.SplitEventSeries)

	router.Post(options.BaseURL+"/v1/events/:eventId/occurrences/:recurrenceId/truncate", wrapper.TruncateEventSeries)

	router.Get(options.BaseURL+"/v1/sources", wrapper.ListSources)

	router.Delete(options.BaseURL+"/v1/sources/:sourceId", wrapper.DeleteSource)

	router.Get(options.BaseURL+"/v1/sources/:sourceId", wrapper.GetSource)

	router.Patch(options.BaseURL+"/v1/sources/:sourceId", wrapper.UpdateSource)

	router.Get(options.BaseURL+"/v1/settings", wrapper.GetSettings)

	router.Patch(options.BaseURL+"/v1/settings", wrapper.UpdateSettings)

	router.Get(options.BaseURL+"/v1/reminders/status", wrapper.GetReminderStatus)

	router.Get(options.BaseURL+"/v1/integrations/:integration/sources", wrapper.ListIntegrationSources)

	router.Delete(options.BaseURL+"/v1/integrations/:integration/sources/:externalId", wrapper.DeleteIntegrationSource)

	router.Get(options.BaseURL+"/v1/integrations/:integration/sources/:externalId", wrapper.GetIntegrationSource)

	router.Put(options.BaseURL+"/v1/integrations/:integration/sources/:externalId", wrapper.RegisterIntegrationSource)

	router.Post(options.BaseURL+"/v1/integrations/:integration/sources/:externalId/sync", wrapper.SyncIntegrationSource)

	router.Get(options.BaseURL+"/v1/integrations/changes", wrapper.ListChanges)

}
